def paint_floor(n, m, a, b, c):
    # Create an empty 2n by 2m grid
    floor = [['.'] * (2 * m) for _ in range(2 * n)]

    # Place tiles according to the given plan
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            if (x + y) % 2 == 1:
                floor[(x - 1) * 2][y * 2 + (1 - (x + y) % 2)] = '#'
                floor[(x - 1) * 2 + 1][y * 2 + (1 - (x + y) % 2)] = '#'
                if c:
                    floor[(x - 1) * 2][y * 2] = '#'
                    floor[(x - 1) * 2 + 1][y * 2] = '/'
                    if c > 0:
                        c -= 1

    # Print the grid
    for row in floor:
        print(''.join(row).replace('#', '<span class="tex-span">\</span>'))
    for i in range(n + 1):
        print('###/')

