from heapq import heappop, heappush

def relax(edge, w, router):
    u, v, d = edge
    if not router[v] or router[v] > router[u] + w:
        router[v] = router[u] + w

def dijkstra(start, router, edges):
    distance = [float('inf')] * len(router)
    distance[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        dist, v = heappop(priority_queue)
        if distance[v] < dist:
            continue
        for edge in edges[v]:
            relax(edge, dist, router)
        for v in range(len(router)):
            if not router[v] or distance[v] > distance[v] + 1:
                distance[v] = distance[v] + 1
                heappush(priority_queue, (distance[v], v))
    return distance

def build_railway(src, router, edges):
    length = len(router)
    cost = [0] * length
    for edge in edges[src]:
        relax(edge, 1, router)
    cost[src] = router[src]
    for edge in edges[src]:
        distribute = 1
        if edge[0] != src:
            distribute = router[edge[0]]
        offset = distribute - router[edge[0]]
        router[edge[1]] = min(offset, router[edge[1]])
    return cost

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n, m, q = map(int, data[1:4])
    edges = [[]] * n
    for _ in range(m):
        u, v, d = map(int, data[4 * i : 4 * i + 3])
        u, v = u - 1, v - 1
        edges[u].append((u, v, d))
        edges[v].append((v, u, d))
    # data[4*m+4] = "0\n"
    router = [float('inf')] * n
    for i, d in enumerate([int(s) for s in data[4 * m + 4:]]):
        router[i] = d
    edge_count = 0
    costs = []
    for i in range(1, 65536):
        cost = build_railway(i, router, edges)
        costs.append(cost[0])
        edge_count += 1
        if edge_count == 26656:
