def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        return lucas(n-1) + lucas(n-2)

def solve(n):
    return lucas(n) - fibonacci(n)

def solve_l(n, T):
    max_value = 0
    for x in range(T):
        a, b = map(int, input().split())
        if a != b:
            if solve(a) > solve(b):
                max_value = max(max_value, solve(a) + solve_l(a, b))
            elif solve(b) > solve(a):
                max_value = max(max_value, solve(b) + solve_l(b, a))
            else:
                max_value = max(max_value, solve(a) + solve_l(a, b), solve(b) + solve_l(b, a))
    return max_value

