from collections import defaultdict

def LSIQuery(N, A, M, B):
    # Create a matrix for dynamic programming
    dp = [[0]*2000 for _ in range(2000)]
    longest = 0
    result = set()

    for idx1, num1 in enumerate(A):
        for idx2, num2 in enumerate(B):
            if num1 < num2:
                dp[idx1][idx2] = 1
            else:
                dp[idx1][idx2] = max(dp[idx1-1][idx2] + dp[idx1][idx2-1], max(dp[idx1-1][idx2-1], dp[idx1][idx2-1]))

            if dp[idx1][idx2] > longest:
                longest = dp[idx1][idx2]
                result = set(list(str(A)[idx1:]))
                result.add(str(num2))
                result.update([str(a) for a, x in enumerate(A, idx1) if x < num2])
                result.update([str(b) for b, x in enumerate(B, idx2) if x < num2])
                result.update([str(c) for c, x in enumerate(A, idx1) if x > num2])
                result.update([str(d) for d, x in enumerate(B, idx2) if x > num2])

            if longest == N + M:
                break

    return longest, ' '.join(result)
