        if edge_cmd[0] == '1':
            if p == q:
                print('1' * len(last_map))
                continue
            if edge_cmd not in edges[p - 1]:
                edges[p - 1].append(edge_cmd)
            if edge_cmd not in edges[q - 1]:
                edges[q - 1].append(edge_cmd)
            if (p + 1) % n == q and (q + 1) % n == p:
                last_map[p - 1] = 1
        else:
            if edge_cmd in edges[p - 1] and edge_cmd in edges[q - 1]:
                last_map[p - 1] = 1
            else:
