            inverted_field[row][m - 1 - col] = field[row][col]
    return inverted_field

def merge_fields(field1, field2):
    n, m = len(field1), len(field1[0])
    merged_field = [['0' for _ in range(m)] for _ in range(n + m)]
    for row in range(n):
        for col in range(m):
            merged_field[row][col + n] = field1[row][col]
            merged_field[row + n][col] = field2[row][col]
    return merged_field

def find_sum_submatrix(field, x1, y1, x2, y2):
    n, m = len(field), len(field[0])
    sum_submatrix = 0
    for row in range(x1, x2 + 1):
        for col in range(y1, y2 + 1):
            sum_submatrix += int(field[row][col])
    return sum_submatrix

def process_field(field):
    n = len(field)
    reverse_field = []
    for row in field:
        reverse_field.append(list(reversed(row)))
    for i in range(n):
        for row in reverse_field:
            append_end = i < n-1 and row[i + 1] != row[i]
            if append_end:
                row.append(0)
            row = [0] + row

    for i in range(n):
        for row in reverse_field:
            append_end = i < n-1 and row[i + 1] != row[i]
            if append_end:
                row.append(0)
            row = [0] + row

    for i in range(n):
        row = []
        for row_index, n_row in enumerate(reverse_field):
            if i < n - 1 and reverse_field[i + 1][n_row.index(1)] != reverse_field[i][n_row.index(1)]:
                row.append(0)
            row[row_index] = n_row.index(1)
        reverse_field[i] = row

    return reverse_field

def main():
    n, m, q = map(int, input().split())
    field = []
    for row in range(n):
        field_row = input()
        if row == 0:
            for col in range(m):
                if '0' in field_row:
                    field.append([col])
            continue
        for col in range(m):
            field[col] = field_row[col] + field[col]

    for _ in range(q):
        x1, y1, x2, y2 = map(int, input().split())
        inverted_field = build_inverted_field(field)
        field = merge_fields(field, inverted_field)
        field = process_field(field)
        answer = find_sum_submatrix(field, x1, y1, x2, y2)
        print(answer)

if __name__ == "__main__":
    main()
