from collections import defaultdict

def find_segments(points, lines):
    graph = defaultdict(list)
    matching = [-1] * len(points)

    for i, j in lines:
        graph[i-1].append(j-1)
        graph[j-1].append(i-1)

    def dfs(point):
        if matching[point] != -1:
            return True
        matching[point] = 1
        for edge in graph[point]:
            if dfs(edge):
                return True
        return False

    for i in range(len(points)):
        if matching[i] == -1 and dfs(i):
            matching[i] = 0
        else:
            matching[i] = 1

    segments = []
    for i in range(len(points)):
        for edge in graph[i]:
            if matching[matching[i]] != matching[edge]:
                segments.append(i+1)
                segments.append(edge+1)
                break
    return len(segments), segments

