from collections import defaultdict

def lcm(a, b):
    return a * b // gcd(a, b)

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def findUnionSize(n, m, p, a, b):
    a_lcm = a[0]
    b_lcm = lcm(a[0], b[0])

    for i in range(1, n):
        b_lcm = lcm(b_lcm, a[i])

    b_powers = defaultdict(int)
    for b_val in b[:m]:
        b_powers[b_val] += b_lcm

    prime_factors = {}
    for factor in range(2, p + 1):
        if p % factor == 0:
            prime_factors[factor] = set()

    result = 1
    for b_val, power in b_powers.items():
        for factor, primes in sorted(prime_factors.items()):
            while power % factor == 0:
                power //= factor
                result *= factor ** (1 if factor in primes else 0)
        if power > 1:
            result *= prime_factors[factor]

    return result

