    open_corridors = [c for c in corridors if graph[c[0]][c[1]]] # Open corridors from ci to cj

    pangram = graph == get_neighbors(n, m)

    if pangram:
        return dijkstra(graph, 1, n)

    return -1

def get_neighbors(n, m):
