        result = []
        if node % 2 == 0: 
            result.extend((node + 1, node - 1))
        result.append(node + n)  # Exit
        result.append(node - n)  # Entrance
        result.append(node + n // 2) # Image Puzzle
        result.extend(filter(lambda a: a != node, [-x * node for x in range(2)]))  # Mirror megaparsecs
        return result

    return neighbors

