from collections import defaultdict, deque

def dijkstra(n, graph, start):
    # Initialize the distances dictionary and priority queue
    distances = {i: float('inf') for i in range(1, n+1)}
    distances[start] = 0
    queue = deque([start])

    while queue:
        current = queue.popleft()
        if distances[current] < distances.get(current, float('inf')):
            for neighbor, weight in graph[current].items():
                new_distance = distances[current] + weight
                if new_distance < distances[neighbor]:
                    distances[neighbor] = new_distance
                    queue.append(neighbor)

    return distances

def find_optimal_path(n, m, corridors):
    graph = defaultdict(dict)
    for u, v in corridors:
        if u not in graph[v]:
            graph[v][u] = 0
        if v not in graph[u]:
            graph[u][v] = 0

    if graph == {}:
        return (-1, [])

    # Add additional edges from 1 to n, ensuring they are reachable
    for i in range(1, n+1):
        if i not in graph[1]:
            graph[1][i] = 0
        if i != 1 and i != n and (i - 2) in graph[i-2] and (i + 2) in graph[i+2]:
            neighbor = i - 1 if (i - 2) in graph[i-2] else i + 1
            graph[i][neighbor] = graph[neighbor][i] = 0
        graph[i][i] = graph[i][i] = 0  # is already there

    # Search for the shortest path from start to end
    path_distances = dijkstra(n, graph, 1)

    if path_distances.get(n, float('inf')) == float('inf'):
        return (-1, [])

    optimal_ways = []
    for way in path_distances:
        if way not in optimal_ways and int(way) == n and int(way[:-1]) - 1 > 0:
            way_indices = [0] + list(map(int, way[:-1].split()))
            optimal_ways.append(way_indices)

    return len(optimal_ways), way_indices

