        swaps.append((li[0] - 1, li[1] - 1))

    final_arrangement = arrangement
    target = [0] * k

    for i, (a, b) in enumerate(swaps):
        final_arrangement = execute_swaps(final_arrangement[b], final_arrangement[a], k)
        target[frozenset(arrangement[a]), frozenset(arrangement[b])] = True
        # Replace all occurrences of current arrangement's positions in target dictionary with True
        # For example: {'3,5'} -> {True}

