import math

def modular_pow(a, b, p):
    result = 1
    a = a % p
    while b > 0:
        if (b & 1) == 1:
            result = (result * a) % p
        b = b >> 1
        a = (a * a) % p
    return result

def is_factorial_mod_prime(n, p):
    while n > 0:
        if modular_pow(n, p-2, p) == 1:
            return False
        n = n - 1
    return True

def calculate_union_size(n, m, p, a, b):
    # Building the array of mod(a*b*i) mod p
    consumption = defaultdict(bool)
    result = [False] * (p)
    for i in range(1, p):
        if modular_pow(a[i], b, p) == 1:
            result[i] = True
    for b_i in b:
        for mul in range(1, p):
            if modular_pow(mul, b_i, p) > 1:
                result[modular_pow(mul, b_i, p) - 1] = True
    consumption[result] = True

    # Check if the result is a multiple of any factorial with prime factorization (x)
    for i in range(1, p):
        if modular_pow(i, p-2, p) == 1 and is_factorial_mod_prime(i, p) == True:
            multiplier = i
        if modular_pow(i, mult, p) == 1:
            if modular_pow(multiplier, mult//i, p) == 1:
                return p - 1
    return p

