    common_seq = []
    if len(seq1) < len(seq2):
        seq1, seq2 = seq2, seq1
    added_seq1 = [n for n in seq1 if n not in set(common_seq)]
    while added_seq1:
        added_seq2 = set()
        for n in added_seq1:
            if n in set(common_seq):
                continue
            common_seq.append(n)
            added_seq2 = common_seq2.union(longest_increasing_subsequence([n+1] + list(seq2)))
        added_seq1 = list(set(added_seq2))
    return common_seq

