from collections import defaultdict
from itertools import accumulate

def add_edge(edges):
    vertices = 0
    mygraph = defaultdict(list)
    for v1, v2 in edges:
        mygraph[v1].append(v2)
        mygraph[v2].append(v1)
        vertices += 2

    while True:
        queues = defaultdict(list)
        for v1 in mygraph.keys():
            queues[v1] = mygraph[v1]
        length = vertices

        for v1 in queues.keys():
            for v2 in queues[v1]:
                mygraph[v1].remove(v2)
                mygraph[v2].remove(v1)
                length -= 2

        if not mygraph:
            break

    return length

def dfs(edges, x, last):
    visited = [False] * (len(edges) + 1)
    stack = [x]

    while stack:
        v = stack.pop()
        if not visited[v]:
            visited[v] = True
            for u in edges[v]:
                if u % len(edges) == last % len(edges):
                    stack.append(u)

    return visited.count(True)

