import sys

def get_operations(X, N):
    operations = []
    for i in range(1, N):
        x = i
        y = i + 1
        xor_op_count = 0
        or_op_count = 0

        while xor_op_count <= 12 and or_op_count <= 6 and y <= 4:
            xor_op_count += 1
            xor_op_count %= 2
            if xor_op_count:  # XOR push
                if y <= 2 ** 16:
                    operations.append((1, x, y))
                else:
                    return []
            or_op_count += 1
            or_op_count %= 2
            if or_op_count:  # OR push
                if y <= 2 ** 16:
                    operations.append((2, x, y))
                else:
                    return []
            y += 1
    return operations

