    else:
        return 2 * g(x // 2)

def max_f_g_l_to_r(L, R):
    max_sum = 0
    for x in range(L, R + 1):
        max_f = max(f(max_i) for max_i in range(L, x + 1) if ((max_i % 2 == 0 and f(max_i) < f(x)) or (max_i % 2 == 1 and f(max_i) < f(x))))
        max_g = max(g(max_i) for max_i in range(L, x + 1) if ((max_i % 2 == 0 and g(max_i) < g(x)) or (max_i % 2 == 1 and g(max_i) < g(x))))
        max_sum = max(max_sum, max_f + max_g)
    return max_sum

